               resp.getcontenttype
           );
         }
+
+        // Every 25 items yield the event loop to avoid blocking the main thread
+        // and appearing unresponsive.
+        if (++this.shouldYieldEventLoop == 25) {
+          await new Promise(resolve => setTimeout(resolve));
+          this.shouldYieldEventLoop = 0;
+        }
         break;
